import backtrader as bt
import math


class MeanVarianceStrategy(bt.Strategy):
    params = (
        ("risk_aversion", 2.5),
        ("minimum_weight", -1.0),
        ("maximum_weight", 1.0),
        ("volatility_floor", 0.005),
    )

    def __init__(self):
        log_return = bt.indicators.ApplyN(
            self.data.close,
            period=2,
            func=lambda closes: math.log(closes[-1] / closes[-2]),
        )
        self.expected_return = bt.indicators.SMA(log_return, period=252)
        self.atr = bt.indicators.ATR(self.data, period=63)
        self.order = None
        self.rebalanced_year_month = None

    def next(self):
        year_month = (self.data.datetime.date(0).year, self.data.datetime.date(0).month)
        if year_month == self.rebalanced_year_month or self.order is not None:
            return

        volatility = self.atr[0] / self.data.close[0]
        if volatility < self.p.volatility_floor:
            weight = 0.0
        else:
            raw_weight = self.expected_return[0] / (
                self.p.risk_aversion * volatility * volatility
            )
            weight = max(
                self.p.minimum_weight,
                min(self.p.maximum_weight, raw_weight),
            )

        self.order = self.order_target_percent(target=weight)
        self.rebalanced_year_month = year_month

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None
